def compute(vars):
    thereafter = vars["v1"]
    total_maturities = vars["v2"]

    if total_maturities == 0:
        return None

    ratio = thereafter / total_maturities
    percentage = ratio * 100

    return {
        "value": percentage,
        "trace": {
            "thereafter": thereafter,
            "total_maturities": total_maturities,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
